    return () => {
        let resp = JSON.parse(result)
        let novels = resp.body.contents
            .filter(item => item.kind === "novel")
            .flatMap(item => {
                return item.thumbnails.map(novel => {
                    novel.tags = novel.tags.map(tag => tag.name)
