                body {
                    margin: 0;
                    padding: 0;
                    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
                    background: #f5f5f5;
                    color: #333;
                }
                .header {
                    padding: 15px;
                    background: linear-gradient(135deg, #6e48aa, #9d50bb);
                    color: white;
                    text-align: center;
                    font-size: 1.2em;
                    box-shadow: 0 2px 5px rgba(0,0,0,0.1);
                }
                .audio-container {
                    width: 100%;
