                }
                .info-label {
                    font-weight: bold;
                    color: #6e48aa;
                }
                .cover-img {
                    width: 100%;
                    max-height: 300px;
                    object-fit: contain;
                    margin-bottom: 15px;
                }
            </style>
        </head>
        <body>
            <div class="header">{{book.name}}</div>
            <div class="audio-container">
                <img src="{{book.coverUrl}}" class="cover-img" onerror="this.style.display='none'">
                <audio controls autoplay>
                    <source src="${mp3Url}" type="audio/mpeg">
                    您的浏览器不支持音频元素
                </audio>
            </div>
            <div class="info-panel">
                <div class="info-item">
                    <span class="info-label">👤 作者：</span>{{book.author}}
                </div>
                <div class="info-item">
                    <span class="info-label">🔖 分类：</span>{{book.kind}}
                </div>
                <div class="info-item">
                    <span class="info-label">📝 简介：</span>{{book.intro}}
                </div>
            </div>
        </body>
        </html>
    `);

    // 在浏览器中打开
    dataUrl = 'data:text/html;base64,' + b64;
    java['startBrowser'](dataUrl, '{{book.name}}');
    java['toast']('音频加载中...');

    // 返回结果
    '【刷新正文】播放\n✅MP3直链:\n' + mp3Url;
