loginUrl:
@js:
function login() {
    let une = source.getLoginInfoMap().get("账号")
    let pwd = source.getLoginInfoMap().get("密码")
    if (une && pwd) {
        let pre_header = JSON.stringify({
            "Referer": source.bookSourceUrl + "login.php",
            "Content-Type": "application/x-www-form-urlencoded"
        })
        let body = String('chname=' + une + '&chpass=' + pwd)
        let url = source.bookSourceUrl + 'login_go.php'
        let ck = java.post(url, body, pre_header).cookies()
        let header = JSON.stringify({
            "Cookie": String(ck).match(/\{(.*?)\}/)[1].replace(/,/g, ';')
        })
        source.putLoginHeader(header)
    }
}

